from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    stack = []
    result = []

    for char in paren_string:
        if char == '(':
            stack.append('')
        elif char == ')':
            current = stack.pop()
            if stack:
                stack[-1] += current
            else:
                result.append(current)
        else:
            if stack:
                stack[-1] += char

    return result  # Step 4: Return the list of separated parentheses strings

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

